// non-tools/call methods naturally take the parallel path.
func extractToolNameFromEnv(env *rawEnvelope) string {
	if env == nil || env.Method != "tools/call" {
		return ""
	}
	return extractToolNameRaw(env.Params)
}

func bytesTrimSpace(b []byte) []byte {
	i := 0
	for i < len(b) && (b[i] == ' ' || b[i] == '\t' || b[i] == '\r' || b[i] == '\n') {
		i++
	}
	j := len(b) - 1
	for j >= i && (b[j] == ' ' || b[j] == '\t' || b[j] == '\r' || b[j] == '\n') {
		j--
	}
	return b[i : j+1]
}

// rawEnvelope is the minimally-decoded JSON-RPC 2.0 request envelope.
// id and params are kept as raw jsontext.Value so the dispatcher can
// splice them back into the response (id) and forward them to a tool
// (params) without an intermediate any/map round-trip. See PERF-0041.
type rawEnvelope struct {
	JSONRPC string         `json:"jsonrpc"`
	ID      jsontext.Value `json:"id,omitzero"`
	Method  string         `json:"method"`
	Params  jsontext.Value `json:"params,omitzero"`
}

// rawToolCall is the minimally-decoded params payload for tools/call.
// The inner arguments are forwarded to the tool unchanged. MCP names the
// argument object "arguments"; we also accept the legacy "params" key for
// backward compatibility (G3).
type rawToolCall struct {
	Name      string         `json:"name"`
	Arguments jsontext.Value `json:"arguments,omitzero"`
	Params    jsontext.Value `json:"params,omitzero"`
}

// args returns the argument payload forwarded to the tool, preferring the
// MCP-standard "arguments" key and falling back to the legacy "params" key.
func (c rawToolCall) args() jsontext.Value {
	if len(c.Arguments) > 0 {
		return c.Arguments
	}
	return c.Params
}

// decodeEnvelope parses a single JSON-RPC 2.0 request into rawEnvelope.
// It does not validate the protocol version; that is the caller's job.
func decodeEnvelope(raw jsontext.Value) (*rawEnvelope, error) {
	env := &rawEnvelope{}
	if err := json.Unmarshal(raw, env); err != nil {
		return nil, err
	}
	return env, nil
}

// initRequestedVersion reads the client's requested protocolVersion from a raw
// initialize params payload. Returns "" for empty/malformed/missing inputs so
// the caller falls back to the server's supported version.
func initRequestedVersion(params jsontext.Value) string {
	if len(params) == 0 {
		return ""
	}
	var p struct {
		ProtocolVersion string `json:"protocolVersion"`
	}
	if err := json.Unmarshal(params, &p); err != nil {
		return ""
	}
	return p.ProtocolVersion
}

// extractToolNameRaw reads only the "name" field from a raw tools/call
// params payload without decoding the inner params bytes. Returns ""
// for malformed/missing inputs.
func extractToolNameRaw(params jsontext.Value) string {
	if len(params) == 0 {
		return ""
	}
	var p struct {
		Name string `json:"name"`
	}
	if err := json.Unmarshal(params, &p); err != nil {
		return ""
	}
	return p.Name
}

// extractOwnerArg reads a single string argument named argName from a raw
// tools/call inner params payload (the "params" of {"name":...,"params":...}).
// It is used by the per-tool ownership check (SEC-0027) to read the resource
// owner id from the named call argument. Returns ("", false) when the params
// are empty/malformed, the key is absent, or the value is not a JSON string —
// so the ownership check fails closed on any non-string/missing argument.
func extractOwnerArg(params jsontext.Value, argName string) (string, bool) {
	if len(params) == 0 || argName == "" {
		return "", false
	}
	var m map[string]jsontext.Value
	if err := json.Unmarshal(params, &m); err != nil {
		return "", false
	}
	raw, ok := m[argName]
	if !ok || len(raw) == 0 {
		return "", false
	}
	var s string
	if err := json.Unmarshal(raw, &s); err != nil {
		return "", false
	}
	return s, true
}

// rpcResultEnvelope is the success-response envelope written for
// non-tools/call paths. result is set as a Go value (map/slice/etc).
type rpcResultEnvelope struct {
	JSONRPC string         `json:"jsonrpc"`
	ID      jsontext.Value `json:"id"`
	Result  any            `json:"result"`
}

// rpcErrEnvelope is the error-response envelope.
type rpcErrEnvelope struct {
	JSONRPC string         `json:"jsonrpc"`
	ID      jsontext.Value `json:"id"`
	Error   rpcErrPayload  `json:"error"`
}

type rpcErrPayload struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
}

// handleRaw is the single-request dispatcher operating on a
// minimally-decoded envelope. Returns nil for notifications.
func handleRaw(ctx context.Context, env *rawEnvelope, tools map[string]Tool, buckets map[string]*bucket) any {
	if ctx == nil {
		ctx = context.Background()
	}
	if env.JSONRPC != "2.0" {
		return objErrRaw(env.ID, -32600, "invalid request")
	}
	// Notifications have no id field. jsontext.Value zero-length means
	// the id key was absent or set to null/undefined.
	if isNullID(env.ID) {
		return nil
	}
	switch env.Method {
	case "initialize":
		// G1: MCP initialize handshake. Echo the client's requested
		// protocolVersion when it matches the version we implement, otherwise
		// negotiate down to mcpProtocolVersion. Advertise the tools capability
		// and report serverInfo from the registry (falling back to a stable
		// default name when unset).
		ver := mcpProtocolVersion
		if req := initRequestedVersion(env.Params); req == mcpProtocolVersion {
			ver = req
		}
		name, version := ServerInfo()
		if name == "" {
			name = "genapi-mcp"
		}
		return objResRaw(env.ID, map[string]any{
			"protocolVersion": ver,
			"capabilities": map[string]any{
				"tools": map[string]any{"listChanged": false},
			},
			"serverInfo": map[string]any{
				"name":    name,
				"version": version,
			},
		})
	case "ping":
		// G7: ping result is an empty object per the MCP lifecycle spec.
		return objResRaw(env.ID, map[string]any{})
	case "shutdown":
		return objResRaw(env.ID, map[string]any{})
	case "notifications/initialized", "initialized":
		// G7: post-initialize notification. Real notifications carry no id and
		// emit nothing (handled by the isNullID check above). If a client sends
		// it with an id we acknowledge with an empty result rather than error.
		return objResRaw(env.ID, map[string]any{})
	case "tools/list":
		// A-NEW-8: filter the enumeration by the caller's roles so a tool
		// whose toolRoles[name] requires a role the caller lacks is NOT
		// exposed. Tools that are absent from toolRoles, or mapped to a
		// nil/empty role list, have no requirement and remain visible to
		// every caller — preserving the legacy behaviour when no per-tool
		// role policy is configured. Mirrors the gating tools/call applies
		// at dispatch. Read under configMu so a concurrent SetToolRoles
		// cannot tear the lookup. GEN-2026-05-29-04.
		callerRoles := RolesFromContext(ctx)
		configMu.RLock()
		roles := toolRoles
		descriptors := toolDescriptors
		configMu.RUnlock()
		names := make([]string, 0, len(tools))
		for k := range tools {
			if required, ok := roles[k]; ok && len(required) > 0 {
				if !hasAnyRole(callerRoles, required) {
					continue
				}
			}
			names = append(names, k)
		}
		sort.Strings(names)
		// G2: tools/list emits MCP tool descriptor objects (name + inputSchema,
		// plus title/description when set), not bare name strings. Use the
		// registered descriptor when present; otherwise fall back to a minimal
		// descriptor with an empty-object input schema so every tool still
		// advertises a spec-valid inputSchema.
		out := make([]map[string]any, 0, len(names))
		for _, name := range names {
			entry := map[string]any{"name": name}
			if td, ok := descriptors[name]; ok {
				if len(td.InputSchema) > 0 {
					entry["inputSchema"] = td.InputSchema
				} else {
					entry["inputSchema"] = jsontext.Value(`{"type":"object"}`)
				}
				if td.Title != "" {
					entry["title"] = td.Title
				}
				if td.Description != "" {
					entry["description"] = td.Description
				}
			} else {
				entry["inputSchema"] = jsontext.Value(`{"type":"object"}`)
			}
			out = append(out, entry)
		}
		return objResRaw(env.ID, map[string]any{"tools": out})
	case "tools/call":
		var call rawToolCall
		if len(env.Params) > 0 {
			if err := json.Unmarshal(env.Params, &call); err != nil {
				return objErrRaw(env.ID, -32602, "invalid params")
			}
		}
		if call.Name == "" {
			return objErrRaw(env.ID, -32602, "invalid params")
		}
		fn, ok := tools[call.Name]
		if !ok {
			return objErrRaw(env.ID, -32601, "method not found")
		}
		// Snapshot the role policy, ownership policy, and per-tool timeout
		// under the read lock so a concurrent Set* cannot tear any of them.
		// GEN-2026-05-29-04.
		configMu.RLock()
		roles := toolRoles
		ownership := toolOwnership
		timeout := toolTimeout
		configMu.RUnlock()
		// Per-tool role enforcement (F-AUTH-2). If a required-role
		// policy is registered for this tool, the caller's context (set
		// by ContextWithRoles in the auth path) must carry at least one
		// of the listed roles, or the tool body never runs.
		//
		// Policy-gate denials (role, ownership, rate-limit below) stay
		// JSON-RPC -32000 errors, NOT CallToolResult{isError:true}: they are
		// transport/authorization failures where the tool body never runs, as
		// opposed to a tool that ran and reported a domain error (G5).
		if required, ok := roles[call.Name]; ok && len(required) > 0 {
			if !hasAnyRole(RolesFromContext(ctx), required) {
				AuditMCP.AuthFail("tool", "insufficient role")
				obsx.LogAudit("mcp_tool_role_denied", map[string]any{"tool": call.Name, "required": required})
				return objErrRaw(env.ID, -32000, "insufficient role")
			}
		}
		// Per-tool ownership enforcement (SEC-0027 / OWASP API1:2023 BOLA,
		// MCP surface). If an ownership policy is registered for this tool,
		// the caller's context MUST carry an authenticated subject (set by
		// ContextWithSubject in the auth path) AND the named tools/call
		// argument MUST equal that subject. Fail-closed: a missing subject
		// (e.g. unauthenticated STDIO, which mirrors the role policy's
		// posture — see SetToolOwnership and the SEC-0031 STDIO trust
		// boundary), a missing/empty argument, or any mismatch is denied
		// before the tool body runs. The owner id is read only from the
		// named call argument, never from a spoofable source.
		if argName, ok := ownership[call.Name]; ok && argName != "" {
			sub, haveSub := SubjectFromContext(ctx)
			argVal, haveArg := extractOwnerArg(call.args(), argName)
			if !haveSub || !haveArg || argVal == "" || argVal != sub {
				AuditMCP.AuthFail("tool", "not resource owner")
				obsx.LogAudit("mcp_tool_ownership_denied", map[string]any{"tool": call.Name, "arg": argName})
				return objErrRaw(env.ID, -32000, "not resource owner")
			}
		}
		if buckets != nil {
			if bk, ok := buckets[call.Name]; ok && !bk.Allow() {
				return objErrRaw(env.ID, -32000, "rate limited")
			}
		}
		AuditMCP.ToolCall(call.Name)
		obsx.LogAudit("mcp_tool_call", map[string]any{"tool": call.Name})
		timeoutCtx, cancel := context.WithTimeout(ctx, timeout)
		defer cancel()
		// PERF-0049: the per-tools/call deadline is enforced with
		// context.AfterFunc + context.WithTimeout rather than a separate
		// watchdog goroutine selecting on timeoutCtx.Done(). AfterFunc
		// fires `timedOut` exactly once when timeoutCtx is cancelled (its
		// deadline elapses or a parent ctx is cancelled), so we no longer
		// pay for a second select arm wired to the Done() channel. The
		// tool body still runs in a recovered goroutine because fn is an
		// arbitrary, potentially blocking call we must be able to abandon
		// on timeout. stop() (deferred below) deregisters the AfterFunc on
		// the normal/fast path so a completed call does not leave a timer
		// pending — the original watchdog left timeoutCtx.Done() selection
		// to GC; AfterFunc lets us release the timer eagerly.
		done := make(chan struct {
			out jsontext.Value
			err error
		}, 1)
		gen.SafeGo("mcp-tool-exec", func() {
			o, e := fn(timeoutCtx, call.args())
			done <- struct {
				out jsontext.Value
				err error
			}{o, e}
		})
		timedOut := make(chan struct{})
		stop := context.AfterFunc(timeoutCtx, func() { close(timedOut) })
		defer stop()
		var out jsontext.Value
		var err error
		select {
		case res := <-done:
			out = res.out
			err = res.err
		case <-timedOut:
			// QG-077 (#242): the deadline and a just-in-time result can race.
			// A result already sitting in the buffered done channel MUST win;
			// only report ErrToolTimeout when no result was delivered by
			// decision time.
			select {
			case res := <-done:
				out = res.out
				err = res.err
			default:
				// G5: a timeout is the tool failing to produce a result,
				// surfaced as a CallToolResult{isError:true}, not a JSON-RPC
				// error.
				return objResRaw(env.ID, toolErrorResult(ErrToolTimeout.Error()))
			}
		}
		// A tool that returns timeoutCtx.Err() when the deadline fires must
		// surface the canonical ErrToolTimeout instead of the raw context
		// error (the PERF-0049 deflake). Unlike the previous blanket
		// timeoutCtx.Err() check, this is keyed on the DELIVERED error, so a
		// successfully delivered result whose deadline elapsed in-flight is
		// no longer discarded (QG-077, #242).
		if err != nil && errors.Is(err, context.DeadlineExceeded) {
			return objResRaw(env.ID, toolErrorResult(ErrToolTimeout.Error()))
		}
		if err != nil {
			// G5: the tool ran but reported a domain error. Per MCP this is a
			// successful JSON-RPC response carrying a CallToolResult with
			// isError:true and the message as a text content block — not a
			// protocol-level -32000 error.
			return objResRaw(env.ID, toolErrorResult(err.Error()))
		}
		obsx.LogAudit("mcp_tool_result", map[string]any{"tool": call.Name})
		// G4: wrap the tool's raw output in an MCP CallToolResult. The output
		// bytes always become a text content block (MCP TextContent requires
		// the "text" property). StructuredContent is only set when out is
		// valid JSON — non-JSON tool output (e.g. plain strings, binary debug
		// output) must not cause the marshaling of CallToolResult to fail.
		res := CallToolResult{
			Content: []Content{{Type: "text", Text: string(out)}},
			IsError: false,
		}
		if isValidJSON(out) {
			res.StructuredContent = jsontext.Value(out)
		}
		return objResRaw(env.ID, res)
	default:
		return objErrRaw(env.ID, -32601, "method not found")
	}
}

// isNullID reports whether the JSON-RPC id field was absent or null,
// indicating a notification. We treat a present-but-null id as a
// notification per legacy behavior (handleOne returned nil when m["id"]
// was nil).
func isNullID(v jsontext.Value) bool {
	if len(v) == 0 {
		return true
	}
	t := bytesTrimSpace(v)
	return len(t) == 4 && string(t) == "null"
}

// cloneID copies the id bytes so subsequent reuse of the request buffer
// can't mutate the response.
func cloneID(v jsontext.Value) jsontext.Value {
	if len(v) == 0 {
		return jsontext.Value("null")
	}
	out := make(jsontext.Value, len(v))
	copy(out, v)
	return out
}

func objResRaw(id jsontext.Value, result any) *rpcResultEnvelope {
	return &rpcResultEnvelope{JSONRPC: "2.0", ID: cloneID(id), Result: result}
}

// toolErrorResult builds the MCP CallToolResult for a tool that ran but
// failed (G5): isError:true with the error message as a text content block.
func toolErrorResult(msg string) CallToolResult {
	return CallToolResult{
		Content: []Content{{Type: "text", Text: msg}},
		IsError: true,
	}
}

// isValidJSON reports whether b is a syntactically valid JSON value. It uses
// jsontext.Value.IsValid() which is available in go1.25+ jsontext. An empty
// slice is not valid JSON (there is no JSON value for "nothing").
func isValidJSON(b []byte) bool {
	if len(b) == 0 {
		return false
	}
	return jsontext.Value(b).IsValid()
}

func objErrRaw(id jsontext.Value, code int, msg string) *rpcErrEnvelope {
	return &rpcErrEnvelope{
		JSONRPC: "2.0",
		ID:      cloneID(id),
		Error:   rpcErrPayload{Code: code, Message: msg},
	}
}

// objErr is the parse-failure error envelope used when the request
// body cannot be decoded enough to recover an id field. It always uses
// id=null per JSON-RPC 2.0.
func objErr(id any, code int, msg string) map[string]any {
	return map[string]any{"jsonrpc": "2.0", "id": id, "error": map[string]any{"code": code, "message": msg}}
}

// Helpers for HTTP rate headers
func setRateHeaders(w http.ResponseWriter, limit, remaining int, reset time.Time) {
	w.Header().Set("X-RateLimit-Limit", itoa(limit))
	w.Header().Set("X-RateLimit-Remaining", itoa(remaining))
	w.Header().Set("X-RateLimit-Reset", fmtUnix(reset))
}

func itoa(v int) string          { return strconv.Itoa(v) }
func fmtUnix(t time.Time) string { return strconv.FormatInt(t.Unix(), 10) }

// hasAnyRole reports whether have contains at least one element of want.
// Both slices are expected to be small (a handful of role names), so the
// O(n*m) scan is fine and avoids allocating a set.
func hasAnyRole(have, want []string) bool {
	for _, w := range want {
		for _, h := range have {
			if h == w {
				return true
			}
		}
	}
	return false
}
